def example(tb):
 cid=next(c for c,x in C.items() if tb in x['teaching_blocks'])
 key=cid.split('.')[-1]
 first=re.split(r'(?<=[.!?])\s+(?=[A-Z])',tb['content'].split('\n\n')[0])[0]
 first=re.sub(r'^(Suppose|Imagine|Take) ',lambda m:{'Suppose':'In this fixture,','Imagine':'Review','Take':'Inspect'}[m[1]]+' ',first)
 return first+' '+E[key]
